const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const won=n=>'₩'+Number(n||0).toLocaleString('ko-KR');
const storageGet=(key,fallback)=>{try{return localStorage.getItem(key)||fallback}catch{return fallback}};
const storageSet=(key,value)=>{try{localStorage.setItem(key,value)}catch{}};
const safeList=(k)=>{try{const v=JSON.parse(storageGet(k,'[]'));return Array.isArray(v)?v.filter(x=>typeof x==='string').slice(0,100):[]}catch{return []}};
const state={allProperties:[],compare:new Set(safeList('stayro-compare')),properties:[],sponsored:[],coupons:[],filters:{},engine:'manual',saved:new Set(safeList('stayro-saved')),city:'',q:'',activeProperty:null,adminToken:'',adminData:null,videoResults:[],conversation:null,auth:null,csrf:'',selectedPlan:'growth',userLoc:null,mapPins:[],mapSelected:'',mapCategory:'all',mapCenter:null,mapSearchQuery:''};
let toastTimer;
function toast(s){const el=$('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3800)}
let voiceRec=null;
function startVoice(inputId){
  const input=document.getElementById(inputId)||document.querySelector('input[name=q]');
  if(!input){toast('입력칸을 찾지 못했습니다.');return}
  const Rec=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!Rec){toast('이 브라우저는 음성 입력을 지원하지 않습니다. Chrome에서 마이크를 사용해 주세요.');return}
  if(voiceRec){try{voiceRec.stop()}catch{}voiceRec=null;$$('.voice-mic').forEach(b=>b.classList.remove('listening'));return}
  const rec=new Rec();
  rec.lang='ko-KR';rec.interimResults=true;rec.continuous=false;
  rec.onresult=e=>{let t='';for(let i=e.resultIndex;i<e.results.length;i++)t+=e.results[i][0].transcript;input.value=t.trim();input.dispatchEvent(new Event('input',{bubbles:true}))};
  rec.onerror=()=>{voiceRec=null;$$('.voice-mic').forEach(b=>b.classList.remove('listening'));toast('음성을 인식하지 못했습니다.')};
  rec.onend=()=>{voiceRec=null;$$('.voice-mic').forEach(b=>b.classList.remove('listening'))};
  voiceRec=rec;rec.start();$$('.voice-mic').forEach(b=>b.classList.add('listening'));toast('듣고 있습니다. 검색할 여행을 말해 주세요.');
}
function speakAnswer(text){
  if(!window.speechSynthesis){toast('이 브라우저는 읽어주기를 지원하지 않습니다.');return}
  window.speechSynthesis.cancel();
  const u=new SpeechSynthesisUtterance(String(text||'').slice(0,800));
  u.lang='ko-KR';window.speechSynthesis.speak(u);
}
async function api(path,body,auth=false,chatToken=''){const options={headers:{}};if(state.csrf)options.headers['X-CSRF-Token']=state.csrf;if(chatToken)options.headers['X-Chat-Token']=chatToken;if(body!==undefined){options.method='POST';options.headers['Content-Type']='application/json';options.body=JSON.stringify(body)}if(auth&&state.adminToken)options.headers['X-Admin-Token']=state.adminToken;const r=await fetch(path,options);let j;try{j=await r.json()}catch{throw Error('서버 응답이 올바르지 않습니다.')};if(!r.ok)throw Error(j.error||'요청에 실패했습니다.');return j}
const imageOf=p=>p.photo_url||p.image_url||'/assets/hero.webp';
const isPublic=p=>Boolean(p.public_record);
const isAgoda=p=>p.source==='agoda'||Boolean(p.agoda_hotel_id||p.affiliate_url);
const agodaBookUrl=p=>{const u=String(p.affiliate_url||p.book_url||'').trim();if(u)return u;if(p.agoda_hotel_id)return 'https://www.agoda.com/partners/partnersearch.aspx?hid='+encodeURIComponent(p.agoda_hotel_id)+'&currency=KRW&locale=ko-kr&NumberofAdults=2&NumberofChildren=0&Rooms=1';return ''};
function openPartnerBook(url,name){if(!url)return false;const w=window.open(url,name||'partnerBooking','width=1280,height=860,menubar=yes,toolbar=yes,scrollbars=yes,resizable=yes');if(w){try{w.opener=null}catch{}}return Boolean(w)}
function tripBookUrl(p){const u=String(p.trip_url||'').trim();if(u)return u;const q=[p.name,p.city].filter(Boolean).join(' ');if(!q)return '';return 'https://kr.trip.com/hotels/list?locale=ko-KR&curr=KRW&keyword='+encodeURIComponent(q)}
function agodaBookBtn(p,label){const url=agodaBookUrl(p);if(!url)return '';return `<a class="agoda-book-btn" data-agodabook href="${esc(url)}" target="_blank" rel="nofollow sponsored noopener noreferrer">${label||'아고다최저가'}</a>`}
function tripBookBtn(p){const url=tripBookUrl(p);if(!url)return '';return `<a class="trip-book-btn" data-tripbook href="${esc(url)}" target="_blank" rel="nofollow sponsored noopener noreferrer">트립닷컴최저가</a>`}
function partnerBookBtns(p){const a=agodaBookBtn(p,'아고다최저가');const t=tripBookBtn(p);if(!a&&!t)return '';return `<div class="partner-price-btns">${a}${t}</div>`}
const priceLabel=p=>isAgoda(p)?'아고다·트립닷컴에서 요금 확인':isPublic(p)?'객실 요금 확인':won(p.price)+' / 1박 · 예시';
const mapQuery=p=>encodeURIComponent(p.address||`${p.city} ${p.area} ${p.name}`);
