function photoMarquee(){const photos=[1,2,3,4,5,6,7,8];return `<section class="marquee-section" aria-label="인공지능 여행 콘셉트 이미지 갤러리"><div class="wrap"><span class="eyebrow">여행의 장면 · 인공지능 콘셉트 갤러리</span><h2>머무르고 싶은 순간들</h2><p class="mini-info">아래 이미지는 서로 다른 장소를 표현한 인공지능 제작 콘셉트 이미지입니다. 특정 실제 숙소를 촬영한 사진이 아닙니다.</p></div><div class="marquee-window"><div class="marquee-track">${[...photos,...photos].map((n,i)=>`<div class="marquee-photo"><img loading="lazy" src="/assets/listing-${n}.webp" alt="인공지능 생성 숙소 콘셉트 ${i+1}"><span>인공지능 콘셉트 · ${String(n).padStart(2,'0')}</span></div>`).join('')}</div></div></section>`}
