function storyCards(){return [{cat:'도시 이야기',title:'서울의 작은 골목에서 찾는 느린 하루',txt:'성수의 카페와 동네 산책을 잇는 도시 여행 루트.',img:2},{cat:'바다 이야기',title:'바다를 품은 부산에서의 주말',txt:'오션뷰 숙소와 해변 산책의 황금 같은 시간.',img:4},{cat:'섬 이야기',title:'제주에서 가장 느리게 걷는 방법',txt:'애월의 해안길과 조용한 숙소를 만나는 하루.',img:6}].map(s=>`<article class="story-card"><div class="story-visual" style="background-image:url('/assets/listing-${s.img}.webp')"></div><div class="story-copy"><span class="eyebrow">${s.cat}</span><h3>${s.title}</h3><p>${s.txt}</p><a class="section-link" href="#journal">스토리 살펴보기 ↗</a></div></article>`).join('')}
function discover(){const qs=new URLSearchParams(location.hash.split('?')[1]||'');const q=qs.get('q')||state.q||'';const city=qs.get('city')??state.city;state.q=q;state.city=city;app(`<div class="page-head"><div class="wrap"><span class="eyebrow">나와 맞는 숙소 찾기</span><h1>인공지능 숙소 검색</h1><p>지역, 분위기, 유형과 여행 목적을 자유롭게 입력하고 가장 잘 맞는 숙소를 살펴보세요.</p></div></div><section class="section-tight"><div class="wrap"><form id="filterForm" class="filters"><input name="q" id="filterQuery" class="field-input filter-input" value="${esc(q)}" placeholder="예: 부산 오션뷰 20만원 이하" maxlength="300"><button type="button" class="voice-mic" data-voice-mic="filterQuery" aria-label="음성으로 입력">마이크</button><select class="select-input" name="city" aria-label="여행 지역">${CITY_SET.map(c=>`<option value="${c}" ${city===c?'selected':''}>${c||'전체 지역'}</option>`).join('')}</select><select class="select-input" name="max_price" aria-label="최대 가격"><option value="">예산 제한 없음</option>${[[100000,'10만원 이하'],[150000,'15만원 이하'],[200000,'20만원 이하'],[300000,'30만원 이하']].map(v=>`<option value="${v[0]}">${v[1]}</option>`).join('')}</select><select class="select-input" name="category" id="categoryFilter" aria-label="숙소 유형"><option value="">모든 숙소 유형</option>${CATEGORY_SET.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}</select><button class="filled-btn filter-submit">찾아보기 ↗</button></form><div class="region-strip">${CITY_SET.map(c=>`<button class="region-pill ${city===c?'active':''}" data-city="${c}">${c||'전체'}</button>`).join('')}</div><div class="gallery-browse"><a class="filled-btn" href="#images">▧ 실제 숙소 사진 검색</a><small>공개 라이선스가 확인된 사진만 실제 사진으로 표시합니다.</small></div><div id="resultsArea" style="margin-top:28px"><div class="loading">숙소를 불러오는 중입니다…</div></div></div></section>`);loadSearch(q,city)}
async function loadSearch(q='',city='',other={}){const params=new URLSearchParams({q,city,...other});try{const r=await api('/api/search?'+params);state.properties=r.results;state.sponsored=r.sponsored;state.engine=r.engine;state.filters=r.interpretation;const el=$('#resultsArea');if(!el)return;const aiLabel=r.engine==='openai'?'실제 인공지능 분석':r.engine.startsWith('rules')?'조건 해석 · 인공지능 연동 미설정':'조건 검색';
 const f=r.interpretation||{};const active=[f.city?`지역: ${esc(f.city)}`:'',f.max_price?`예산: ${won(f.max_price)} 이하`:'',...(f.amenities||[]).map(a=>`시설: ${esc(a)}`)].filter(Boolean);
 const sponsoredIds=new Set(r.sponsored.map(p=>p.id));const organicOnly=r.results.filter(p=>!sponsoredIds.has(p.id));
 el.innerHTML=`<div class="notice">검색 엔진: <strong>${aiLabel}</strong> ${r.engine==='rules-fallback'?'· 외부 인공지능 연결 실패로 규칙 기반 검색 적용':''}${active.length?' · '+active.join(' / '):''}</div><div class="layout-spacer"></div><div class="result-count">검색 조건에 맞는 숙소 ${r.count}곳</div>${r.sponsored.length?`<div class="premium-zone"><div class="premium-head"><h3>✦ 프리미엄 파트너 숙소</h3><small>유료 광고 · 검색 조건 적용</small></div>${listingGrid(r.sponsored)}<p class="disclosure">${esc(r.disclosure)}</p></div>`:''}${organicOnly.length?`${sectionTitle('일반 검색 결과','일반 숙소 결과','스폰서 구역에 표시된 숙소는 중복 노출하지 않습니다.')} ${listingGrid(organicOnly)}`:`<div class="empty"><h3>${r.sponsored.length?'일반 숙소 결과는 없습니다.':'일치하는 숙소가 없습니다.'}</h3><p>조건을 조금 더 넓혀 다시 검색해 보세요.</p></div>`}<p class="disclosure">공개자료 기반으로 숙소명·주소를 확인했으며 운영자 인증·실시간 숙박 요금·객실 재고는 확인되지 않았습니다. 가격 조건 검색은 요금 미확인 숙소를 제외합니다.</p>`;bindCommon()}catch(e){const el=$('#resultsArea');if(el)el.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function askPage(){const qs=new URLSearchParams(location.hash.split('?')[1]||'');const q=qs.get('q')||state.q||'';state.q=q;app(`<div class="page-head"><div class="wrap"><span class="eyebrow">길별이 AI</span><h1>여행에게 말해 보세요</h1><p>마이크 또는 글로 물으면 오픈라우터 저비용 모델이 문장을 해석하고, 우리 사이트 숙소 5곳과 관광지를 함께 보여 줍니다. 광고는 월구독 파트너 1건만 표시합니다.</p></div></div><section class="section-tight"><div class="wrap"><form id="askForm" class="search-card ask-search"><div class="search-entry"><span class="search-symbol">✧</span><div style="flex:1"><label>자연어 검색</label><input name="q" id="askQuery" maxlength="300" value="${esc(q)}" placeholder="예: 주말에 가평 펜션, 애견동반 가능한 곳" autocomplete="off" aria-label="인공지능 숙소 검색"></div><button type="button" class="voice-mic" data-voice-mic="askQuery" aria-label="음성으로 입력">마이크</button></div><button type="submit" class="search-button">AI로 찾기 ↗</button></form><div id="askAnswer">${q?'<div class="loading">길별이가 검색 중입니다…</div>':'<div class="empty"><h3>어디로 갈지 말해 주세요.</h3><p>마이크를 누르거나 “속초에서 바다 가까운 모텔”처럼 적어 보세요.</p></div>'}</div></div></section>`);if(q)runAsk(q)}
function adCard(p,q){if(!p)return '';return `<article class="ai-ad-card" data-adclick="${esc(p.id)}" data-adquery="${esc(q)}" tabindex="0" role="link" aria-label="광고 ${esc(p.name)}"><img src="${esc(imageOf(p))}" alt="${esc(p.name)}"><div><span class="ai-ad-kicker">광고 · 월구독 파트너</span><h3>${esc(p.name)}</h3><p>⌖ ${esc(p.city)} · ${esc(p.category||'숙소')}</p><p class="mini-info">AI 검색 결과의 광고 칸 1곳입니다. 클릭·노출은 업주 리포트에 집계됩니다.</p></div></article>`}
function sightCards(sights){if(!sights||!sights.length)return '';return `${sectionTitle('근처 관광지','이 여행에서 같이 가면 좋은 곳','여행갈지도 지역 자료와 해석된 목적지를 기준으로 고른 명소입니다.')}<div class="ai-sights">${sights.map(s=>`<article class="ai-sight"><small>${esc(s.area||'')}</small><b>${esc(s.name)}</b><p>${esc(s.why||'')}</p></article>`).join('')}</div>`}
async function runAsk(q){const el=$('#askAnswer');if(!el)return;el.innerHTML='<div class="loading">길별이가 검색 중입니다…</div>';try{const r=await api('/api/ai/search',{q});state.q=q;const engine=r.engine==='openrouter'?'오픈라우터 저비용 모델':r.engine==='rules-fallback'?'규칙 해석 · 모델 연결 실패':'규칙 해석 · 오픈라우터 키 미설정';el.innerHTML=`<article class="ai-answer"><h2>길별이 답변</h2><p id="aiAnswerText">${esc(r.answer)}</p><div class="ai-answer-actions"><button type="button" class="voice-speak" data-voice-speak>읽어주기</button><button type="button" class="near-button" data-navgo="discover">조건 검색으로 보기</button></div><p class="ai-meta">${esc(engine)}${r.model?' · '+esc(r.model):''}${r.interpretation?.city?' · 지역 '+esc(r.interpretation.city):''}</p></article>${r.ad?adCard(r.ad,q):'<p class="notice">이번 검색에 표시할 월구독 광고가 없습니다. 모텔·펜션 파트너는 가격표에서 광고 칸을 구독할 수 있습니다.</p>'}${r.stays?.length?`${sectionTitle('추천 숙소','우리 사이트에서 고른 5곳','광고와 분리된 일반 추천입니다.')}${listingGrid(r.stays)}`:'<div class="empty"><h3>조건에 맞는 숙소가 없습니다.</h3><p>지역이나 예산을 조금 넓혀 다시 물어 보세요.</p></div>'}${sightCards(r.sights||[])}<p class="disclosure">${esc(r.disclosure||'')}</p>`;bindCommon()}catch(e){el.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
const MAP_STAY_CATEGORY_OPTIONS = [
  ['all','전체','✦'], ['hotel','호텔','🏨'], ['motel','모텔','🛏️'],
  ['pension','펜션·풀빌라','🏡'], ['private','프라이빗 하우스','🏠'],
  ['resort','리조트','🌴'], ['guesthouse','게스트하우스','🎒'],
  ['hanok','한옥','🏯'], ['camping','캠핑·글램핑','⛺'], ['other','기타 숙박','⌂']
];
const GARAK_MARKET_STATION = { lat:37.493060, lng:127.118060, city:'', label:'가락시장역' };
let mapLoadSequence = 0;
function mapCategoryControls(){
  return `<div class="map-category-filter" aria-label="숙소 유형 선택">
    <div class="map-category-title"><img src="/assets/mascot-meomuri.webp" alt="" loading="lazy"><div><strong>머무리와 숙소 유형 고르기</strong><span>원하는 숙소만 지도와 목록에서 찾아보세요</span></div></div>
    <div class="map-category-chips" role="group" aria-label="숙소 유형 필터">${MAP_STAY_CATEGORY_OPTIONS.map(([id,label,icon])=>
      `<button type="button" class="map-category-chip ${state.mapCategory===id?'active':''}" data-mapcategory="${id}" aria-pressed="${state.mapCategory===id}"><span aria-hidden="true">${icon}</span> ${label}</button>`
    ).join('')}</div></div>`;
}
function mapPage(){
  // 이전 세션 위치를 재사용하지 않는다. 위치 권한을 확인하기 전에는 항상 가락시장역을 표시한다.
  state.userLoc=null;
  window.YeohangGeo?.clear?.();
  app(`<div class="page-head"><div class="wrap"><span class="eyebrow">여러 숙소 지도 · 내 주변</span><h1>내 주변 숙소 찾기</h1><p>유형별 주변 숙소를 지도에 여러 핀으로 표시합니다. 위치 권한을 허용하면 가까운 숙소부터 찾고, 선택한 장소의 길찾기는 카카오맵에서 이어집니다.</p></div></div><section class="section-tight"><div class="wrap"><div class="filters"><button class="filled-btn" data-near>⌖ 내 위치 사용</button><button class="region-pill" data-mapcity="서울">서울</button><button class="region-pill" data-mapcity="부산">부산</button><button class="region-pill" data-mapcity="제주">제주</button><button class="region-pill" data-mapcity="강릉">강릉</button>${state.userLoc?'<button class="outline-btn" data-cleargeo>위치 지우기</button>':''}</div>${mapCategoryControls()}<p class="map-geo-status" id="mapGeoStatus" role="status" aria-live="polite">현재 위치를 사용하지 않으면 가락시장역 반경 5km를 표시합니다.</p><div class="map-wrap"><div class="map-canvas" id="mapCanvas"><div id="multiStayMap" class="map-multi-surface" hidden aria-label="주변 숙소 여러 위치를 표시하는 지도"></div><iframe id="googleStayMap" title="Google 지도 예비 화면" loading="lazy" referrerpolicy="no-referrer-when-downgrade" src="${esc(window.YeohangGeo.embedPlace(37.493060,127.118060,'가락시장역'))}"></iframe><a class="map-open-google" id="openGoogleMaps" href="https://www.google.com/maps?q=37.493060,127.118060" target="_blank" rel="noopener noreferrer">구글 지도에서 열기 ↗</a></div><div class="map-side" id="mapSide"><div class="loading">주변 숙소를 불러오는 중입니다…</div></div></div><p class="map-engine-status" id="mapEngineStatus" role="status" aria-live="polite">여러 숙소 지도를 준비하고 있습니다…</p><p class="disclosure">지도 좌표는 숙소 데이터 제공처 자료입니다. 지도 배경 및 저작권 표시는 현재 사용 중인 지도 공급자 안내를 따릅니다. 현재 위치는 브라우저 세션에만 저장되고 계정에는 올리지 않습니다. 길찾기는 카카오맵에서 이어집니다.</p></div></section>`);const start=GARAK_MARKET_STATION;loadGoogleMap(start.lat,start.lng,'');maybeAutoGeo()}
function mapRows(props){return (props||[]).length?props.slice(0,80).map(p=>`<div class="map-list-row ${state.mapSelected===p.id?'active':''}" data-mappin="${esc(p.id)}"><img src="${esc(imageOf(p))}" alt="${esc(p.name)}"><div><h4>${esc(p.name)}</h4><span>⌖ ${esc(p.city)} · ${esc(p.category||'숙소')} ${p.distance_km!==undefined?` · ${esc(p.distance_km)}km`:''}</span><strong>${esc(priceLabel(p))}</strong><div class="map-row-actions"><button type="button" class="near-button" data-mapdir="${esc(p.id)}">카카오맵 길찾기</button>${partnerBookBtns(p)}<a href="/stay/${encodeURIComponent(p.id)}">숙소 보기</a></div></div></div>`).join('') :'<div class="empty"><h3>선택한 유형의 숙소가 없습니다.</h3><p>전체를 선택하거나 다른 지역·숙소 유형을 찾아보세요.</p></div>'}
function showGoogleMap(pin,dir=false){
  const geo=window.YeohangGeo;
  const frame=$('#googleStayMap');
  if(!geo||!pin||pin.lat==null)return;
  if(frame&&!window.YeohangMultiMap?.isReady?.())frame.src=dir&&state.userLoc?geo.embedDir(state.userLoc,pin):geo.embedPlace(pin.lat,pin.lng,pin.name);
  const open=$('#openGoogleMaps');
  if(open)open.href=dir&&state.userLoc?geo.openDir(state.userLoc,pin,'driving'):geo.openPlace(pin.lat,pin.lng,pin.name);
}
async function loadGoogleMap(lat,lng,city=''){
  state.mapCenter={lat,lng,city};
  const seq=++mapLoadSequence;
  const category=state.mapCategory||'all';
  const origin=city?'region':state.userLoc?'gps':'default';
  const params=new URLSearchParams({category,lat:String(lat),lng:String(lng),origin});
  const st=$('#mapGeoStatus');
  if(st)st.textContent='숙소 유형별 결과를 불러오는 중입니다…';
  // 새 유형을 선택하면 이전 유형의 핀을 즉시 제거한다. 느린 응답도 새 필터를 덮어쓸 수 없다.
  window.YeohangMultiMap?.clearPins?.();
  const pendingSide=$('#mapSide');
  if(pendingSide)pendingSide.innerHTML='<div class="loading" role="status">선택한 유형의 숙소를 찾는 중입니다…</div>';
  try {
    const r=await api('/api/map?'+params);
    if(seq!==mapLoadSequence||nav()!=='map')return;
    state.mapPins=(r.pins||[]).filter(p=>Number.isFinite(p.distance_km)&&p.distance_km<=5);
    state.properties=state.mapPins;
    const side=$('#mapSide');
    if(side)side.innerHTML=mapRows(state.mapPins);
    const pin=state.mapPins.find(p=>p.id===state.mapSelected)||state.mapPins[0];
    state.mapSelected=pin?.id||'';
    showGoogleMap(pin||{lat,lng,name:city|| (origin==='default'?'가락시장역':'내 위치')},false);
    if(window.YeohangMultiMap){
      window.YeohangMultiMap.render({pins:state.mapPins,center:{lat,lng},originLabel:origin==='default'?'가락시장역 · 기본 위치 (실제 위치 아님)':origin==='gps'?'현재 위치':'지역 검색 중심',userLoc:origin==='gps'?state.userLoc:null,selectedId:state.mapSelected,onSelect:(id,fromMap)=>selectMapPin(id,false,Boolean(fromMap))});
    }
    const label=(MAP_STAY_CATEGORY_OPTIONS.find(([id])=>id===category)||[])[1]||'전체';
    const context=city|| (origin==='gps'?'내 위치 주변':'가락시장역 기준 (실제 내 위치 아님)');
    if(st)st.textContent=`${context} · 반경 5km · ${label} ${state.mapPins.length}곳 (최대 80곳 표시). 선택한 숙소 유형만 지도에 표시됩니다.`;
  } catch(e) {
    if(seq!==mapLoadSequence)return;
    const side=$('#mapSide');if(side)side.innerHTML='<div class="empty"><h3>숙소를 불러오지 못했습니다.</h3><p>잠시 후 다시 시도해 주세요.</p></div>';
    if(st)st.textContent='숙소 검색 중 오류가 발생했습니다.';
    toast(e.message);
  }
}
async function nearMe(){if(!window.YeohangGeo){toast('지도 모듈을 불러오지 못했습니다.');return}toast('위치 접근 권한을 확인하고 있습니다.');try{const loc=await window.YeohangGeo.request();state.userLoc=loc;if(nav()!=='map'){location.hash='#map';return}await loadGoogleMap(loc.lat,loc.lng,'');toast('내 위치 반경 5km 숙소를 표시했습니다.')}catch(e){toast(e.message)}}
async function mapCity(city){const coords={'서울':[37.5665,126.978],'부산':[35.1796,129.0756],'제주':[33.4996,126.5312],'강릉':[37.7519,128.8761]};const c=coords[city]||[GARAK_MARKET_STATION.lat,GARAK_MARKET_STATION.lng];state.mapSelected='';await loadGoogleMap(c[0],c[1],city)}
async function maybeAutoGeo(){
  try {
    if(!navigator.permissions?.query)return;
    const perm=await navigator.permissions.query({name:'geolocation'});
    if(nav()!=='map')return;
    if(perm.state==='denied'){
      if(state.userLoc){
        state.userLoc=null;
        window.YeohangGeo?.clear?.();
        // 사용자가 지역을 직접 고른 경우에는 임의로 검색 중심을 덮어쓰지 않는다.
        if(!state.mapCenter?.city)await loadGoogleMap(GARAK_MARKET_STATION.lat,GARAK_MARKET_STATION.lng,'');
      }
      return;
    }
    if(perm.state==='granted'&&!state.userLoc)await nearMe();
  }catch{}
}
function selectMapPin(id,dir=false,fromMap=false){
  const pin=state.mapPins.find(p=>p.id===id);
  if(!pin)return;
  state.mapSelected=id;
  showGoogleMap(pin,dir);
  if(!fromMap)window.YeohangMultiMap?.select?.(id,true,!dir);
  $$('.map-list-row').forEach(el=>el.classList.toggle('active',el.dataset.mappin===id));
  if(fromMap){const row=$$('.map-list-row').find(el=>el.dataset.mappin===id);row?.scrollIntoView({behavior:'smooth',block:'nearest'});}
  // 현재 위치 권한이 없어도 외부 지도에서 목적지 길찾기를 시작할 수 있다.
}

/* V9: 카카오맵 공식 URL 링크 연동, 실시간 경로 안내는 외부 앱에서 수행.
 * 5km 서버 필터/사용자 위치 동의/유형별 비동기 요청을 건드리지 않는다. */
function navVisiblePins(){
  const q=String(state.mapSearchQuery||'').trim().toLocaleLowerCase('ko');
  if(!q)return state.mapPins;
  return state.mapPins.filter(p=>[p.name,p.city,p.area,p.category,p.address].some(v=>String(v||'').toLocaleLowerCase('ko').includes(q)));
}
function navRedrawPins(){
  if(nav()!=='map')return 0;
  const shown=navVisiblePins();
  const side=$('#mapSide');
  if(side)side.innerHTML=mapRows(shown);
  if(!shown.some(p=>p.id===state.mapSelected))state.mapSelected=shown[0]?.id||'';
  const center=state.mapCenter||GARAK_MARKET_STATION;
  const gps=state.mapCenter?.city ? null : state.userLoc;
  window.YeohangMultiMap?.render?.({
    pins:shown,center,userLoc:gps,
    originLabel:gps?'현재 위치':state.mapCenter?.city?'지역 검색 중심':'가락시장역 · 기본 위치 (실제 위치 아님)',
    selectedId:state.mapSelected,
    onSelect:(id,fromMap)=>selectMapPin(id,false,Boolean(fromMap))
  });
  const count=$('#mapGeoStatus');
  if(count)count.textContent='선택한 숙소 유형 · 반경 5km · 검색 일치 '+shown.length+'곳';
  return shown.length;
}
window.YeohangNavigation=Object.freeze({
  search(query){state.mapSearchQuery=String(query||'').slice(0,100);return navRedrawPins();},
  openDirections(){
    const pin=state.mapPins.find(p=>p.id===state.mapSelected);
    if(!pin||!window.YeohangMultiMap?.validPoint?.(pin))return false;
    // Kakao Maps 공식 Web URL 규격. 로케이션 권한이 없더라도 목적지만 전달한다.
    const dest=encodeURIComponent(String(pin.name||'목적지'))+','+Number(pin.lat)+','+Number(pin.lng);
    const url='https://map.kakao.com/link/to/'+dest;
    window.location.assign(url);
    return true;
  }
});
function placesPage(){const qs=new URLSearchParams(location.hash.split('?')[1]||'');const city=qs.get('city')||'';const q=qs.get('q')||'';const cities=['','서울','부산','제주','경주','전주','가평','속초','강릉'];app(`<div class="page-head"><div class="wrap"><span class="eyebrow">한국관광공사 · 유튜브 · 블로거</span><h1>국내 명소를 지역으로 찾기</h1><p>관광공사 TourAPI와 유튜브 Data API, 구글 블로거 공식 연동만 사용합니다. 상세 페이지에서 소개·지도·쇼츠·브이로그·근처 숙소를 함께 봅니다.</p></div></div><section class="section-tight"><div class="wrap"><form id="placesForm" class="filters"><input name="q" class="field-input filter-input" value="${esc(q)}" placeholder="예: 경복궁, 해수욕장" maxlength="80"><select name="city" class="select-input">${cities.map(c=>`<option value="${esc(c)}" ${c===city?'selected':''}>${c||'전체 지역'}</option>`).join('')}</select><button class="filled-btn">지역 검색</button></form><div class="region-strip">${cities.map(c=>`<a class="region-pill ${c===city?'active':''}" href="#places?city=${encodeURIComponent(c)}">${c||'전체'}</a>`).join('')}</div><div id="placesArea" class="loading">명소를 불러오는 중입니다…</div></div></section>`);loadPlaces(city,q)}
async function loadPlaces(city='',q=''){const el=$('#placesArea');if(!el)return;try{const r=await api('/api/places?'+new URLSearchParams({city,q}));el.innerHTML=`<div class="result-count">${r.count}곳 · ${r.tourapi?'TourAPI 연결됨':'TourAPI 키 미설정 · 샘플'} · ${r.youtube?'유튜브 API 연결됨':'유튜브 키 미설정'}</div><div class="directory-list place-grid">${(r.places||[]).map(p=>`<article class="directory-item"><span class="directory-top">${esc(p.city)} · ${esc(p.category)}</span><h2><a href="/place/${encodeURIComponent(p.id)}">${esc(p.name)} ↗</a></h2><p>${esc((p.overview||'').slice(0,90))}…</p></article>`).join('')||'<div class="empty">이 지역 명소가 없습니다.</div>'}`;}catch(e){el.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function journal(){app(`<div class="page-head"><div class="wrap"><span class="eyebrow">여행 저널</span><h1>구글 블로그로 만나는 여행</h1><p>공개된 구글 블로거 여행 글을 공식 연동으로 확인하고 숙소·명소 정보와 연결합니다. 국내 명소 소개는 <a href="#places">지역별 명소</a>에서 이어집니다.</p></div></div><section class="section-tight"><div class="wrap"><div class="blog-layout"><article class="blog-leading"><img src="/assets/hero.webp" alt="인공지능으로 제작한 여행 숙소 콘셉트"><div class="story-copy"><span class="eyebrow">에디터 노트</span><h2 style="margin:10px 0">숙소의 이야기를 검색에 연결하는 방법</h2><p>숙소 운영자는 블로거에 글을 발행하고 여행갈지도가 공식 연동으로 공개 게시글 제목·링크를 불러와 연결합니다. 검색과 예약 문의, 채팅은 여행갈지도에서 처리합니다.</p><span class="badge">구글 블로거 중심 콘텐츠 구조</span></div></article><div><div class="blog-post"><span class="eyebrow">블로그 연결</span><h3>숙소별 블로그 콘텐츠 연동</h3><p>각 업체가 블로그 ID를 연결하면 공개 게시글을 공식 블로거 연동으로 조회하고, 원문은 블로거로 연결합니다.</p><form id="bloggerForm"><input id="blogIdInput" class="field-input" type="text" inputmode="numeric" placeholder="블로거 숫자 아이디" required><button class="filled-btn" style="margin-top:10px">공개 글 불러오기</button></form><div id="bloggerResult" class="mini-info" style="margin-top:13px">API 키와 실제 블로그 ID 설정 후 연동됩니다.</div></div><div class="blog-post"><span class="eyebrow">숙소 스토리</span><h3>검색에 강한 숙소 스토리</h3><p>지역 명소·찾아가는 방법·객실 정보·실제 사진 출처 등 고유한 정보를 쌓습니다. Google 검색의 상위 노출은 보장하지 않습니다.</p></div><div class="blog-post"><span class="eyebrow">콘텐츠 권리</span><h3>저작권을 확인한 콘텐츠만</h3><p>인공지능 콘셉트 이미지와 실제 숙소 사진을 구분하고, 제휴·소유자 승인 사진을 별도 보관합니다.</p></div></div></div><div class="layout-spacer"></div>${sectionTitle('추천 여행 루트','이번 주 여행 아이디어','가상 여행 콘셉트를 활용해 만든 에디토리얼 예시입니다. 실제 방문·검증 후기와 구분됩니다.')}<div class="story-grid">${storyCards()}</div></div></section>`)}
function shorts(){const qs=new URLSearchParams(location.hash.split('?')[1]||'');const city=qs.get('city')||'제주';const cities=['서울','부산','제주','경주','전주','가평','속초','강릉'];app(`<div class="page-head"><div class="wrap"><span class="eyebrow">유튜브 Data API</span><h1>지역별 여행 쇼츠와 브이로그</h1><p>인기 여행 유튜버와 한국관광공사 공식 채널의 공개 영상만 유튜브 Data API로 큐레이션합니다. 페이지를 긁어오지 않습니다.</p></div></div><section class="section-tight"><div class="wrap"><div class="region-strip">${cities.map(c=>`<a class="region-pill ${c===city?'active':''}" href="#shorts?city=${encodeURIComponent(c)}">${c}</a>`).join('')}</div><form id="videoForm" class="filters"><input name="q" class="field-input filter-input" placeholder="예: 제주 여행 브이로그" value="${esc(city+' 여행')}" maxlength="100"><button class="filled-btn">유튜브에서 찾기</button></form><div id="videoApiResults"><div class="loading">${esc(city)} 영상을 불러오는 중입니다…</div></div><p class="disclosure">쇼츠는 유튜브 videoDuration=short 공식 필터입니다. 키 미설정 시 유튜브 검색 링크로 연결합니다. 영상 다운로드·재업로드는 제공하지 않습니다.</p></div></section>`);loadCityMedia(city)}
async function loadCityMedia(city){const el=$('#videoApiResults');if(!el)return;try{const r=await api('/api/media/curate?'+new URLSearchParams({city}));const card=v=>`<a class="place-video" href="https://www.youtube.com/watch?v=${encodeURIComponent(v.id)}" target="_blank" rel="noopener noreferrer"><img src="${esc(v.thumbnail)}" alt=""><b>${esc(v.title)}</b><small>${v.kind==='shorts'?'쇼츠':'영상'} · ${esc(v.channel)}</small></a>`;const creators=(r.creators||[]).map(c=>`<span class="region-pill">${esc(c.name)}</span>`).join('');el.innerHTML=`<p class="mini-info">큐레이션 채널 ${creators||'한국관광공사 VisitKorea 등'}</p>${r.shorts?.length?`<h3>쇼츠</h3><div class="place-videos">${r.shorts.map(card).join('')}</div>`:`<p class="notice">쇼츠가 아직 없습니다. <a href="${esc(r.search?.shorts||'#')}" target="_blank" rel="noopener noreferrer">${esc(city)} 쇼츠 검색 ↗</a></p>`}${r.videos?.length?`<h3 style="margin-top:22px">브이로그</h3><div class="place-videos">${r.videos.map(card).join('')}</div>`:`<p class="notice">영상이 아직 없습니다. <a href="${esc(r.search?.videos||'#')}" target="_blank" rel="noopener noreferrer">${esc(city)} 브이로그 검색 ↗</a></p>`}${r.posts?.length?`<h3 style="margin-top:22px">구글 블로그</h3>${r.posts.map(p=>`<p><a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">${esc(p.title)} ↗</a></p>`).join('')}`:''}`;}catch(e){el.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
