document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#overlay').classList.contains('hidden'))closeModal();if(e.key==='Tab'&&!$('#overlay').classList.contains('hidden')){const nodes=$$('button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled])',$('#overlay')).filter(el=>el.getClientRects().length);if(nodes.length){const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-detail]')){e.preventDefault();location.assign('/stay/'+encodeURIComponent(e.target.dataset.detail))}});
document.addEventListener('change',e=>{if(e.target.matches('#bookingForm [name=checkin]')){const form=e.target.form,checkout=form?.elements.checkout;if(checkout&&e.target.value){const d=new Date(e.target.value+'T12:00:00');d.setDate(d.getDate()+1);const minimum=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');checkout.min=minimum;if(!checkout.value||checkout.value<minimum)checkout.value=minimum}}if(e.target.id==='adminPropertySelect'&&state.adminData){const p=state.adminData.properties.find(p=>p.id===e.target.value);if(p)$('#propertyEditArea').innerHTML=editPropertyForm(p)}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['imageSearchForm','heroSearch','askForm','filterForm','placesForm','bloggerForm','videoForm','bookingForm','chatStartForm','chatReplyForm','couponForm','editPropertyForm','adCheckoutForm','adProductForm'].includes(form.id))return;e.preventDefault();const d=formData(form);if(['bookingForm','chatStartForm','couponForm'].includes(form.id))d.privacy_consent=d.privacy_consent==='on';try{switch(form.id){case'imageSearchForm':await loadGallery(d.q||'',d.category||'');break;case'heroSearch':case'askForm':state.q=d.q;state.city='';if(location.hash.startsWith('#ask')){await runAsk(d.q);history.replaceState(null,'','#ask?q='+encodeURIComponent(d.q))}else location.hash='#ask?q='+encodeURIComponent(d.q);break;case'placesForm':location.hash='#places?city='+encodeURIComponent(d.city||'')+'&q='+encodeURIComponent(d.q||'');if(location.hash.startsWith('#places'))await loadPlaces(d.city||'',d.q||'');break;case'adCheckoutForm':{const body={sku:d.sku,property_id:d.property_id,email:d.email};if(d.amount_krw)body.amount_krw=Number(d.amount_krw);const r=await api('/api/checkout',body,true);if(r.url)location.assign(r.url);break}case'adProductForm':{if(d.admin_token)state.adminToken=d.admin_token;const r=await api('/api/ad-products',{name:d.name,amount_krw:Number(d.amount_krw),interval:d.interval},true);toast('광고 상품을 저장했습니다: '+r.name);await loadPricing();break}case'filterForm':state.q=d.q;state.city=d.city;location.hash='#discover?q='+encodeURIComponent(d.q)+'&city='+encodeURIComponent(d.city);if(location.hash.includes('#discover?')&&new URLSearchParams(location.hash.split('?')[1]).get('q')===d.q){await loadSearch(d.q,d.city,d.max_price?{max_price:d.max_price,category:d.category}:{category:d.category})}break;case'bloggerForm':{const r=await api('/api/blogger/posts?blog_id='+encodeURIComponent($('#blogIdInput').value));$('#bloggerResult').innerHTML=r.posts.map(p=>`<p><a target="_blank" rel="noopener noreferrer" href="${esc(p.url)}">${esc(p.title)} ↗</a></p>`).join('')||'아직 공개 게시글이 없습니다.';break}case'videoForm':{const r=await api('/api/youtube/search?q='+encodeURIComponent(d.q));$('#videoApiResults').innerHTML=`<div class="story-grid">${r.videos.length?'': '<div class="empty">공개 검색 결과가 없습니다. 검색어를 바꾸어 주세요.</div>'}${r.videos.map(v=>`<article class="story-card"><a href="https://www.youtube.com/watch?v=${encodeURIComponent(v.id)}" target="_blank" rel="noopener noreferrer"><img src="${esc(v.thumbnail)}" alt="${esc(v.title)}" style="width:100%;height:170px;object-fit:cover"><div class="story-copy"><h3>${esc(v.title)}</h3><p>${esc(v.channel)}</p><span class="section-link">유튜브에서 재생 ↗</span></div></a></article>`).join('')}</div>`;break}case'bookingForm':{const r=await api('/api/bookings',{...d,property_id:state.activeProperty.id,guests:Number(d.guests)});$('#detailAction').innerHTML=`<div class="notice"><strong>예약 문의가 접수되었습니다.</strong><p>접수 번호: ${esc(r.booking_id)}</p><p>시연용 계산금액: ${won(r.amount)}${r.promo_discount?` · 쿠폰 예시 할인 ${won(r.promo_discount)}`:``}</p><p>${esc(r.notice)}</p></div>`;toast('예약 문의를 저장했습니다.');break}case'chatStartForm':{const r=await api('/api/chat/start',{...d,property_id:state.activeProperty.id});state.conversation={id:r.conversation_id,token:r.token};$('#detailAction').innerHTML=chatThread();showChat();toast('채팅 문의가 접수되었습니다.');break}case'chatReplyForm':{if(!state.conversation)throw Error('대화가 없습니다.');await api('/api/chat/send',{conversation_id:state.conversation.id,token:state.conversation.token,message:d.message},!!state.adminToken);form.reset();showChat();break}case'couponForm':{const r=await api('/api/coupons/claim',{coupon_id:form.dataset.couponid,email:d.email,privacy_consent:d.privacy_consent==='on'});$('#modalContent').innerHTML=`<div class="modal-body" style="text-align:center;padding:55px 30px"><span class="eyebrow">내 쿠폰</span><h2>${r.discount_pct}% 쿠폰 발급</h2><p>아래 코드를 예약 문의에서 입력하세요.</p><h2 style="font-family:monospace;background:#eff6f0;border-radius:12px;padding:16px">${esc(r.token)}</h2><button class="filled-btn" data-copy="${esc(r.token)}">쿠폰 코드 복사</button><p class="mini-info">데모 쿠폰 · 실제 숙박 할인 아님</p></div>`;break}case'editPropertyForm':{const obj={id:d.id,youtube_url:d.youtube_url,photo_url:d.photo_url,photo_license:d.photo_license};if(!(state.auth?.authenticated&&!state.auth.admin))Object.assign(obj,{price:Number(d.price),sponsored:d.sponsored==='1',blog_url:d.blog_url,blog_id:d.blog_id});const r=await api(state.auth?.authenticated&&!state.auth.admin?'/api/partner/property':'/api/admin/property',obj,true);toast('숙소 정보를 저장했습니다.');await loadAdmin();break}}}catch(err){toast(err.message)}});
